# file: textkit.py
class WordCounter:
    """Counts words, case-insensitively, ignoring punctuation."""

    def __init__(self, text):
        self.words = [w.strip('.,!?').lower() for w in text.split()]

    def count(self, word):
        return sum(1 for w in self.words if w == word.lower())

    def most_common(self):
        best, best_n = None, 0
        for w in set(self.words):
            n = self.count(w)
            if n > best_n:
                best, best_n = w, n
        return best
