from .pricing import discounted


class Stock:
    def __init__(self):
        self.items = {}

    def add(self, name, qty):
        self.items[name] = self.items.get(name, 0) + qty

    def remove(self, name, qty):
        if self.items.get(name, 0) < qty:
            raise ValueError('not enough')
        self.items[name] -= qty

    def value(self, prices, discount_pct=0):
        return sum(discounted(prices[n], discount_pct) * q for n, q in self.items.items())
